97		}
98		if pt.TransferID != "TR-002" || pt.Confirmed ||
99			pt.FromHolder != "李四" || pt.FromLocation != "实验室B" ||
100			pt.ToHolder != "王五" || pt.ToLocation != "实验室C" ||
101			pt.Qty != "6.750" || !pt.HandedOverAt.Equal(hAt2) {
102			t.Fatalf("待确认交接详情被改写: %+v", pt)
103		}
104	}
105	
106	// requireChildIndependent 校验分出的子样始终由李四在实验室B独立持有，
107	// 不受原样任何交接或旧请求重复提交的影响。
108	func requireChildIndependent(t *testing.T, s *Store) {
109		t.Helper()
110		c, err := s.GetSample("S-001-A")
111		if err != nil {
112			t.Fatalf("查询子样: %v", err)
113		}
114		if c.ParentID != "S-001" || c.InitialQty != "3.250" || c.Remaining != "3.250" ||
115			c.Holder != "李四" || c.Location != "实验室B" {
116			t.Fatalf("子样应仍由李四在实验室B独立持有 3.250 毫升: %+v", c)
117		}
118		if c.PendingTransfer != nil {
119			t.Fatalf("子样不应被原样交接带动出待确认记录: %+v", c.PendingTransfer)
120		}
121		if len(c.History) != 1 || c.History[0].Kind != "split" {
122			t.Fatalf("子样保管历史不应变化: %+v", c.History)
123		}
124	}
125	
126	// TestStaleHandoverResubmitDuringNextPending 覆盖第二次交接尚未确认时，
127	// 重新提交第一次交接的相同交出/接收请求：必须幂等返回第一次交接的已确认
128	// 记录，当前持有人已不是张三、当前剩余量已不是 10.000 都不能影响结果，
129	// 也不能清除 TR-002 的待确认记录或另建交接。
130	func TestStaleHandoverResubmitDuringNextPending(t *testing.T) {
131		s, hAt1, rAt1, hAt2, _ := setupDivergedHandover(t)
132		tokyo := time.FixedZone("UTC+9", 9*60*60)
133	
134		pBefore, err := s.GetSample("S-001")
135		if err != nil {
136			t.Fatal(err)
137		}
138		historyBefore := len(pBefore.History) // register / TR-001 交出 / TR-001 接收 / split / TR-002 交出
139	
140		// 重新提交第一次交接的相同交出信息：编号、人员、地点带首尾空白，
141		// 时间换一个时区表示同一实际时刻。
142		oldHandover := HandoverInput{
143			TransferID: " TR-001 ", SampleID: " S-001 ",
144			FromHolder: " 张三 ", FromLocation: " 实验室A ",
145			ToHolder: " 李四 ", ToLocation: " 实验室B ",
146			HandedOverAt: hAt1.In(tokyo),
147		}
148		tr, err := s.Handover(oldHandover)
149		if err != nil {
150			t.Fatalf("旧交出请求重复提交应成功返回旧记录: %v", err)
151		}
152		requireOldFirstTransfer(t, tr, hAt1, rAt1)
153		if len(s.data.Transfers) != 2 {
154			t.Fatalf("旧交出请求不能另建交接, got %d 条", len(s.data.Transfers))
155		}
156	
157		p, err := s.GetSample("S-001")
158		if err != nil {
159			t.Fatal(err)
160		}
161		requireParentMidSecondHandover(t, p, hAt2)
162		if len(p.History) != historyBefore {
163			t.Fatalf("旧交出请求不能追加历史: before=%d after=%d", historyBefore, len(p.History))
164		}
165	
166		// 重新提交第一次交接的相同接收信息：旧接收请求不能清除新的待确认记录。
167		oldConfirm := ConfirmInput{
168			TransferID: " TR-001 ",
169			Receiver:   " 李四 ",
170			AtLocation: " 实验室B ",
171			ReceivedAt: rAt1.In(tokyo),
172		}
173		tr, err = s.Confirm(oldConfirm)
174		if err != nil {
175			t.Fatalf("旧接收请求重复提交应成功返回旧记录: %v", err)
176		}
177		requireOldFirstTransfer(t, tr, hAt1, rAt1)
178	
179		p, err = s.GetSample("S-001")
180		if err != nil {
181			t.Fatal(err)
182		}
183		requireParentMidSecondHandover(t, p, hAt2)
184		if len(p.History) != historyBefore {
185			t.Fatalf("旧接收请求不能追加历史: before=%d after=%d", historyBefore, len(p.History))
186		}
187		tr2, err := s.GetTransfer("TR-002")
188		if err != nil {
189			t.Fatal(err)
190		}
191		if tr2.Confirmed || tr2.Qty != "6.750" {
192			t.Fatalf("新交接 TR-002 应仍待确认且保持 6.750: %+v", tr2)
193		}
194	
195		// 子样仍由李四在实验室B独立持有。
196		requireChildIndependent(t, s)
197	
198		// 旧保管事件本身也不能被改写。
199		if p.History[1].Kind != "transfer-out" || p.History[1].Holder != "张三" ||
200			p.History[1].Location != "实验室A" || !p.History[1].Time.Equal(hAt1) {
201			t.Fatalf("第一次交出的历史事件被改写: %+v", p.History[1])
202		}
203		if p.History[2].Kind != "transfer-in" || p.History[2].Holder != "李四" ||
204			p.History[2].Location != "实验室B" || !p.History[2].Time.Equal(rAt1) {
205			t.Fatalf("第一次接收的历史事件被改写: %+v", p.History[2])
206		}
207	
208		// 沿用旧编号但改变目的地点：ErrConflict，旧交接与当前样品状态都保留。
209		badHandover := HandoverInput{
210			TransferID: "TR-001", SampleID: "S-001",
211			FromHolder: "张三", FromLocation: "实验室A",
212			ToHolder: "李四", ToLocation: "实验室C",
213			HandedOverAt: hAt1,
214		}
215		if _, err := s.Handover(badHandover); !errors.Is(err, ErrConflict) {
216			t.Fatalf("沿用旧编号改目的地点应返回 ErrConflict, got %v", err)
217		}
218		// 把旧接收时间改成另一个合法时刻（不早于旧交出时间）：同样 ErrConflict。
219		badConfirm := ConfirmInput{"TR-001", "李四", "实验室B", rAt1.Add(2 * time.Hour)}
220		if _, err := s.Confirm(badConfirm); !errors.Is(err, ErrConflict) {
221			t.Fatalf("旧接收改时间应返回 ErrConflict, got %v", err)
222		}
223	
224		// 冲突拒绝后：旧记录、当前状态、待确认详情、历史条数全部不变。
225		tr, err = s.GetTransfer("TR-001")
226		if err != nil {
227			t.Fatal(err)
228		}
229		requireOldFirstTransfer(t, tr, hAt1, rAt1)
230		p, _ = s.GetSample("S-001")
231		requireParentMidSecondHandover(t, p, hAt2)
232		if len(p.History) != historyBefore {
233			t.Fatalf("被拒绝的旧请求不能改动历史: before=%d after=%d", historyBefore, len(p.History))
234		}
235		if len(s.data.Transfers) != 2 {
236			t.Fatalf("被拒绝的旧请求不能新增交接, got %d 条", len(s.data.Transfers))
237		}
238		requireChildIndependent(t, s)
239	
240		// 王五按新交接约定确认接收：正常完成，只产生这一次接收应有的历史。
241		rAt2 := hAt2.Add(time.Hour)
242		done, err := s.Confirm(ConfirmInput{"TR-002", "王五", "实验室C", rAt2})
243		if err != nil {
244			t.Fatalf("新交接确认接收: %v", err)
245		}
246		if !done.Confirmed || done.Qty != "6.750" || done.ConfirmedBy != "王五" {
247			t.Fatalf("新交接确认结果错误: %+v", done)
248		}
249		p, _ = s.GetSample("S-001")
250		if p.Holder != "王五" || p.Location != "实验室C" || p.PendingTransfer != nil {
251			t.Fatalf("新交接确认后应由王五在实验室C持有且结束待确认: %+v", p)
252		}
253		if p.Remaining != "6.750" {
254			t.Fatalf("新交接确认后原样剩余量应为 6.750, got %s", p.Remaining)
255		}
256		wantKinds := []string{"register", "transfer-out", "transfer-in", "split", "transfer-out", "transfer-in"}
257		if len(p.History) != len(wantKinds) {
258			t.Fatalf("确认后历史条数错误: %+v", p.History)
259		}
260		for i, k := range wantKinds {
261			if p.History[i].Kind != k {
262				t.Fatalf("确认后历史顺序错误: %+v", p.History)
263			}
264		}
265		last := p.History[len(p.History)-1]
266		if last.Holder != "王五" || last.Location != "实验室C" || !last.Time.Equal(rAt2) {
267			t.Fatalf("最后一条历史应只属于 TR-002 的接收: %+v", last)
268		}
269		// 旧交接记录与独立子样依旧不变。
270		tr, _ = s.GetTransfer("TR-001")
271		requireOldFirstTransfer(t, tr, hAt1, rAt1)
272		requireChildIndependent(t, s)
273	}
274	
275	// TestStaleHandoverResubmitAfterNextConfirmed 覆盖第二次交接完成后，再次
276	// 提交第一次交接的相同请求：仍返回旧交接记录，原样继续由王五在实验室C
277	// 持有，不回到李四处，也不重新进入待确认；改内容仍是 ErrConflict。
278	func TestStaleHandoverResubmitAfterNextConfirmed(t *testing.T) {
279		s, hAt1, rAt1, _, rAt2 := setupDivergedHandover(t)
280		tokyo := time.FixedZone("UTC+9", 9*60*60)
281	
282		if _, err := s.Confirm(ConfirmInput{"TR-002", "王五", "实验室C", rAt2}); err != nil {
283			t.Fatalf("第二次交接接收: %v", err)
284		}
285		pBefore, _ := s.GetSample("S-001")
286		if pBefore.Holder != "王五" || pBefore.Location != "实验室C" || pBefore.PendingTransfer != nil {
287			t.Fatalf("前置状态错误: %+v", pBefore)
288		}
289		historyBefore := len(pBefore.History)
290	
291		// 完成后再提交第一次交接的相同交出与接收请求（空白与换时区的同等表示）。
292		oldHandover := HandoverInput{
293			TransferID: "\tTR-001\t", SampleID: " S-001 ",
294			FromHolder: " 张三 ", FromLocation: " 实验室A ",
295			ToHolder: " 李四 ", ToLocation: " 实验室B ",
296			HandedOverAt: hAt1.In(tokyo),
297		}
298		tr, err := s.Handover(oldHandover)
299		if err != nil {
300			t.Fatalf("新交接完成后旧交出请求仍应幂等返回: %v", err)
301		}
302		requireOldFirstTransfer(t, tr, hAt1, rAt1)
303	
304		oldConfirm := ConfirmInput{
305			TransferID: " TR-001 ",
306			Receiver:   " 李四 ",
307			AtLocation: " 实验室B ",
308			ReceivedAt: rAt1.In(tokyo),
309		}
310		tr, err = s.Confirm(oldConfirm)
311		if err != nil {
312			t.Fatalf("新交接完成后旧接收请求仍应幂等返回: %v", err)
313		}
314		requireOldFirstTransfer(t, tr, hAt1, rAt1)
315	
316		p, _ := s.GetSample("S-001")
317		if p.Holder != "王五" || p.Location != "实验室C" {
318			t.Fatalf("旧请求不能让原样回到李四手中: %+v", p)
319		}
320		if p.PendingTransfer != nil {
321			t.Fatalf("旧请求不能让原样重新进入待确认: %+v", p.PendingTransfer)
322		}
323		if p.Remaining != "6.750" || len(p.History) != historyBefore {
324			t.Fatalf("旧请求不能改动剩余量或历史: rem=%s history=%d->%d",
325				p.Remaining, historyBefore, len(p.History))
326		}
327		if len(s.data.Transfers) != 2 {
328			t.Fatalf("旧请求不能新增交接记录, got %d 条", len(s.data.Transfers))
329		}
330		tr2, _ := s.GetTransfer("TR-002")
331		if !tr2.Confirmed || tr2.ConfirmedBy != "王五" || tr2.Qty != "6.750" {
332			t.Fatalf("新交接完成状态被旧请求改写: %+v", tr2)
333		}
334		requireChildIndependent(t, s)
335	
336		// 完成后改旧请求内容仍须拒绝，且旧交接、当前样品状态都保留。
337		badHandover := oldHandover
338		badHandover.ToLocation = "实验室C"
339		if _, err := s.Handover(badHandover); !errors.Is(err, ErrConflict) {
340			t.Fatalf("完成后沿用旧编号改目的地点应 ErrConflict, got %v", err)
341		}
342		badConfirm := ConfirmInput{"TR-001", "李四", "实验室B", rAt1.Add(2 * time.Hour)}
343		if _, err := s.Confirm(badConfirm); !errors.Is(err, ErrConflict) {
344			t.Fatalf("完成后旧接收改时间应 ErrConflict, got %v", err)
345		}
346	
347		tr, _ = s.GetTransfer("TR-001")
348		requireOldFirstTransfer(t, tr, hAt1, rAt1)
349		p, _ = s.GetSample("S-001")
350		if p.Holder != "王五" || p.Location != "实验室C" || p.PendingTransfer != nil ||
351			p.Remaining != "6.750" || len(p.History) != historyBefore {
352			t.Fatalf("冲突拒绝后当前状态被改动: %+v", p)
353		}
354		requireChildIndependent(t, s)
355	}
356

